/* ===== Storage & game state ===== */
var LS={get:function(k,d){try{var v=localStorage.getItem('fern2-'+k);if(v!==null)return JSON.parse(v);}catch(e){}try{var o=localStorage.getItem('fern-'+k);return o?JSON.parse(o):d;}catch(e){return d;}},set:function(k,v){try{localStorage.setItem('fern2-'+k,JSON.stringify(v));}catch(e){}}};
LANG=LS.get('lang','th');if(LANG!=='en')LANG='th';
var todayStr=new Date().toDateString();
var G={xp:LS.get('xp',0),hearts:LS.get('hearts',{n:5,d:todayStr}),streak:LS.get('streak',{n:0,last:''}),goal:LS.get('goal',{d:todayStr,xp:0}),lessons:LS.get('lessons-done',[]),mistakes:LS.get('mistakes',[]),dailyDone:LS.get('daily-done','')};
if(G.hearts.d!==todayStr)G.hearts={n:5,d:todayStr};
if(G.goal.d!==todayStr)G.goal={d:todayStr,xp:0};
function saveG(){LS.set('xp',G.xp);LS.set('hearts',G.hearts);LS.set('streak',G.streak);LS.set('goal',G.goal);LS.set('lessons-done',G.lessons);LS.set('mistakes',G.mistakes);LS.set('daily-done',G.dailyDone);}
function touchStreak(){var y=new Date(Date.now()-864e5).toDateString();if(G.streak.last===todayStr)return;G.streak.n=(G.streak.last===y)?G.streak.n+1:1;G.streak.last=todayStr;saveG();}
function addXP(n){G.xp+=n;G.goal.xp+=n;touchStreak();saveG();renderHUD();toast('⭐ +'+n+' XP');}
function level(){return Math.floor(G.xp/100)+1;}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;');}
function subjById(id){for(var i=0;i<SUBJECTS.length;i++)if(SUBJECTS[i].id===id)return SUBJECTS[i];return null;}
function subjName(s){return LANG==='en'?SUBJ_EN[s.id]+(s.id==='saraban'?'':' · '+s.name):s.name;}
function toast(msg){var d=document.createElement('div');d.className='toast';d.textContent=msg;document.getElementById('fx').appendChild(d);setTimeout(function(){d.remove();},1600);}
function confetti(){var c=document.createElement('div');c.className='confetti';var cols=['#58cc02','#1cb0f6','#ffc800','#ff4b4b','#ce82ff'];for(var i=0;i<60;i++){var p=document.createElement('i');p.style.left=Math.random()*100+'%';p.style.background=cols[i%5];p.style.animationDuration=(1.4+Math.random()*1.4)+'s';p.style.animationDelay=(Math.random()*.4)+'s';c.appendChild(p);}document.getElementById('fx').appendChild(c);setTimeout(function(){c.remove();},3400);}
function celebrate(title,body,btnTxt,cb){confetti();var r=document.getElementById('modal-root');r.innerHTML='<div class="modal"><div style="text-align:center"><div>'+mascotSVG(110,'cheer')+'</div><div class="big">'+esc(title)+'</div><p class="mut">'+body+'</p><button class="btn" id="cel-btn">'+esc(btnTxt)+'</button></div></div>';document.getElementById('cel-btn').addEventListener('click',function(){r.innerHTML='';if(cb)cb();});}
function renderHUD(){document.getElementById('hud-xp').textContent=G.xp;document.getElementById('hud-streak').textContent=G.streak.n;document.getElementById('hud-hearts').textContent=G.hearts.n;document.getElementById('hud-level').textContent=level();var pct=Math.min(100,Math.round(G.goal.xp/30*100));document.getElementById('goal-bar').style.width=pct+'%';document.getElementById('goal-txt').textContent=G.goal.xp+' / 30 XP';var ring=document.getElementById('ring');if(ring){ring.style.strokeDashoffset=226-226*pct/100;document.getElementById('ring-txt').textContent=pct+'%';}document.getElementById('mistake-n').textContent=G.mistakes.length;var m2=document.getElementById('mistake-n2');if(m2)m2.textContent=G.mistakes.length;}
/* ===== Navigation ===== */
function go(name){document.querySelectorAll('.view').forEach(function(v){v.classList.remove('on');});var el=document.getElementById('v-'+name);if(el)el.classList.add('on');document.querySelectorAll('nav.tabs button').forEach(function(b){b.classList.toggle('on',b.getAttribute('data-go')===name);});window.scrollTo(0,0);}
document.querySelectorAll('nav.tabs button').forEach(function(b){b.addEventListener('click',function(){go(b.getAttribute('data-go'));});});
document.getElementById('lang-th').addEventListener('click',function(){LANG='th';LS.set('lang','th');applyLang();});
document.getElementById('lang-en').addEventListener('click',function(){LANG='en';LS.set('lang','en');applyLang();});
/* ===== Countdown ===== */
var EXAM_TS=new Date('2026-11-29T13:30:00+07:00').getTime();
function tick(){var diff=EXAM_TS-Date.now();if(diff<=0){['cd-d','cd-h','cd-m','cd-s'].forEach(function(id){var e=document.getElementById(id);if(e)e.textContent='0';});return;}var s=Math.floor(diff/1000);var set=function(id,v){var e=document.getElementById(id);if(e)e.textContent=v;};set('cd-d',Math.floor(s/86400));set('cd-h',Math.floor(s%86400/3600));set('cd-m',Math.floor(s%3600/60));set('cd-s',s%60);}
tick();setInterval(tick,1000);
/* ===== Split lessons: 3 bite lessons per subject ===== */
function lessonParts(id){var html=(LANG==='en'?LESSONS_EN[id]:LESSONS[id]);var chunks=html.split('<h3>');var parts=[];chunks.forEach(function(c,i){if(!c.trim())return;parts.push((i>0?'<h3>':'')+c);});if(parts.length<2)parts=[html];return parts.slice(0,3);}
function lessonKey(sid,pi){return sid+'-'+pi;}
function openLesson(sid,pi){var s=subjById(sid);var parts=lessonParts(sid);var key=lessonKey(sid,pi);var r=document.getElementById('modal-root');var body=parts[pi]||parts[0];var done=G.lessons.indexOf(key)>=0;r.innerHTML='<div class="modal"><div><div style="display:flex;justify-content:space-between;align-items:center"><div class="big" style="font-size:21px;margin:0">'+s.icon+' '+esc(subjName(s))+' · '+(pi+1)+'/'+parts.length+'</div><button class="xbtn" id="m-x">✕</button></div><div class="lesson-body">'+body+'</div><div style="display:grid;gap:10px;margin-top:16px"><button class="btn" id="m-done">'+(done?'✓ ':'')+t('lessonDone')+' +15 XP</button><button class="btn blue" id="m-quiz">'+t('startQuiz')+' →</button></div></div></div>';document.getElementById('m-x').addEventListener('click',function(){r.innerHTML='';});document.getElementById('m-done').addEventListener('click',function(){if(!done){G.lessons.push(key);addXP(15);}r.innerHTML='';renderAll();checkBadges(true);});document.getElementById('m-quiz').addEventListener('click',function(){r.innerHTML='';startQuiz(sid);});}
/* ===== Path + lists ===== */
function renderPath(){var h='';var unitIdx=0;SUBJECTS.forEach(function(s){var c=SUBJ_COLOR[s.id];var parts=lessonParts(s.id);var doneN=parts.filter(function(_,pi){return G.lessons.indexOf(lessonKey(s.id,pi))>=0;}).length;var sc=LS.get('quiz-'+s.id,null);h+='<div class="unit-banner" style="background:'+c[0]+'"><span>'+t('unit')+' '+(++unitIdx)+' · '+s.icon+' '+esc(subjName(s))+'</span><span>'+s.n+' '+t('qs')+'</span></div>';parts.forEach(function(_,pi){var key=lessonKey(s.id,pi);var idx=SUBJECTS.indexOf(s)*3+pi;var unlocked=idx===0||G.lessons.indexOf(lessonKey(SUBJECTS[Math.floor((idx-1)/3)].id,(idx-1)%3))>=0||G.lessons.indexOf(key)>=0;var done=G.lessons.indexOf(key)>=0;var off=pi===1?'off-r':pi===2?'off-l':'';h+='<div class="node '+off+(unlocked?'':' lock')+'"><button class="bub" data-node="'+s.id+':'+pi+':'+(unlocked?1:0)+'" style="--c:'+(done?'#ffc800':unlocked?c[0]:'#e5e5e5')+';--cd:'+(done?'#e0a800':unlocked?c[1]:'#c9c9c9')+';background:'+(done?'#ffc800':unlocked?c[0]:'#e5e5e5')+';box-shadow:0 6px 0 '+(done?'#e0a800':unlocked?c[1]:'#c9c9c9')+'">'+(done?'⭐':unlocked?s.icon:'🔒')+'</button><div class="stars">'+(done?'★★★':'☆☆☆')+'</div><div class="lbl">'+(LANG==='en'?'Lesson':'บทที่')+' '+(pi+1)+'</div><div class="sub">'+esc(subjName(s))+'</div></div>';});var qp=QUESTIONS[s.id].length;h+='<div class="node"><button class="bub" data-practice="'+s.id+'" style="background:#fff;border:3px solid '+c[0]+';box-shadow:0 6px 0 '+c[1]+'">✏️</button><div class="lbl">'+(LANG==='en'?'Practice':'ฝึกข้อสอบ')+' · '+qp+' '+t('qs')+'</div><div class="sub">'+(sc?(t('score')+' '+sc.best+'/'+qp):'')+'</div></div>';});document.getElementById('path').innerHTML=h;document.querySelectorAll('[data-node]').forEach(function(b){b.addEventListener('click',function(){var p=b.getAttribute('data-node').split(':');if(p[2]==='0'){toast(t('locked'));return;}openLesson(p[0],+p[1]);});});document.querySelectorAll('[data-practice]').forEach(function(b){b.addEventListener('click',function(){startQuiz(b.getAttribute('data-practice'));});});
 var ll='';SUBJECTS.forEach(function(s){var parts=lessonParts(s.id);parts.forEach(function(_,pi){var done=G.lessons.indexOf(lessonKey(s.id,pi))>=0;ll+='<div class="card" style="display:flex;gap:12px;align-items:center;padding:14px 16px"><span style="font-size:30px">'+s.icon+'</span><div style="flex:1"><b style="font-family:var(--font)">'+esc(subjName(s))+' · '+(LANG==='en'?'Lesson':'บทที่')+' '+(pi+1)+'</b><div class="mut">'+(done?'✓ '+(LANG==='en'?'Completed':'เรียนจบแล้ว'):'2–3 '+(LANG==='en'?'min':'นาที'))+'</div></div><button class="chip'+(done?' on':'')+'" data-open-lesson="'+s.id+':'+pi+'">'+(done?'✓':t('readLesson'))+'</button></div>';});});document.getElementById('learn-list').innerHTML=ll;document.querySelectorAll('[data-open-lesson]').forEach(function(b){b.addEventListener('click',function(){var p=b.getAttribute('data-open-lesson').split(':');openLesson(p[0],+p[1]);});});
 var ql='';SUBJECTS.forEach(function(s){var sc2=LS.get('quiz-'+s.id,null);ql+='<div class="card" style="display:flex;gap:12px;align-items:center;padding:14px 16px"><span style="font-size:30px">'+s.icon+'</span><div style="flex:1"><b style="font-family:var(--font)">'+esc(subjName(s))+'</b><div class="mut">'+QUESTIONS[s.id].length+' '+t('qs')+(sc2?' · '+t('score')+' '+sc2.best+'/'+QUESTIONS[s.id].length:'')+'</div></div><button class="chip" data-start-quiz="'+s.id+'">▶ '+t('start')+'</button></div>';});document.getElementById('quiz-list').innerHTML=ql;document.querySelectorAll('[data-start-quiz]').forEach(function(b){b.addEventListener('click',function(){startQuiz(b.getAttribute('data-start-quiz'));});});}
/* ===== Badges ===== */
var BADGES=[['🌱','First leaf / ใบแรก','xp>=10'],['🔥','3-day streak / ไฟ 3 วัน','streak>=3'],['⭐','100 XP','xp>=100'],['🏅','300 XP','xp>=300'],['📚','All lessons / ครบบทเรียน','lessons>=18'],['🃏','Flashcard pro / เซียนการ์ด','fc>=25'],['🎯','Mock finisher / จบสอบจำลอง','mock>=1'],['👮','Mock passer / สอบผ่านจำลอง','mockpass>=1']];
function badgeState(){return{xp:G.xp,streak:G.streak.n,lessons:G.lessons.length,fc:LS.get('fc-known',[]).length,mock:LS.get('mock-history',[]).length,mockpass:LS.get('mock-history',[]).filter(function(x){return x.pass;}).length};}
function renderBadges(){var st=badgeState();var h='';BADGES.forEach(function(b){var parts=b[2].split('>=');var on=st[parts[0]]>=+parts[1];var nm=LANG==='en'?b[1].split(' / ')[0]:b[1].split(' / ')[1]||b[1];h+='<div class="badge'+(on?'':' off')+'"><span class="em">'+b[0]+'</span><div><b style="font-family:var(--font)">'+esc(nm)+'</b><div class="mut">'+(on?'✓ '+(LANG==='en'?'Unlocked':'ปลดล็อกแล้ว'):'🔒 '+b[2])+'</div></div></div>';});document.getElementById('badges').innerHTML=h;}
var lastBadgeCount=-1;
function checkBadges(celeb){var st=badgeState();var n=BADGES.filter(function(b){var p=b[2].split('>=');return st[p[0]]>=+p[1];}).length;if(lastBadgeCount>=0&&n>lastBadgeCount&&celeb){celebrate('🏆 '+(LANG==='en'?'New badge!':'เหรียญใหม่!'),BADGES.map(function(b){var p=b[2].split('>=');return st[p[0]]>=+p[1]?b[0]+' '+b[1]:null;}).filter(Boolean).join(' · '),t('continue'),null);}lastBadgeCount=n;}
/* ===== Quiz engine (MCQ + hearts + XP + mistakes) ===== */
var quiz=null;
function heartsGate(){if(G.hearts.n<=0){toast(t('noHearts'));return false;}return true;}
function startQuiz(id){if(!heartsGate())return;quiz={mode:'subject',id:id,list:QUESTIONS[id].map(function(q,i){return{sid:id,idx:i,q:q};}),i:0,score:0};go('quiz');document.getElementById('quiz-menu').hidden=true;renderQ();}
function startDaily(){if(!heartsGate())return;var pool=[];SUBJECTS.forEach(function(s){QUESTIONS[s.id].forEach(function(q,i){pool.push({sid:s.id,idx:i,q:q});});});var day=Math.floor(Date.now()/864e5);var list=[];for(var k=0;k<10;k++)list.push(pool[(day*7+k*13)%pool.length]);quiz={mode:'daily',list:list,i:0,score:0};go('quiz');document.getElementById('quiz-menu').hidden=true;renderQ();}
function startMistakes(){if(!G.mistakes.length){toast(t('noMistakes'));return;}if(!heartsGate())return;var list=G.mistakes.map(function(m){return{sid:m.sid,idx:m.idx,q:QUESTIONS[m.sid][m.idx]};});quiz={mode:'mistakes',list:list,i:0,score:0};go('quiz');document.getElementById('quiz-menu').hidden=true;renderQ();}
function addMistake(sid,idx){if(!G.mistakes.some(function(m){return m.sid===sid&&m.idx===idx;})){G.mistakes.push({sid:sid,idx:idx});saveG();renderHUD();}}
function removeMistake(sid,idx){G.mistakes=G.mistakes.filter(function(m){return !(m.sid===sid&&m.idx===idx);});saveG();renderHUD();}
function renderQ(){var box=document.getElementById('quiz-box');var st=quiz;if(!st)return;if(st.i>=st.list.length){finishQuiz();return;}var item=st.list[st.i];var q=item.q;var s=subjById(item.sid);var pct=Math.round(st.i/st.list.length*100);var h='<div class="prow"><button class="xbtn" onclick="exitQuiz()">✕</button><div class="bar" style="flex:1"><i style="width:'+pct+'%"></i></div><span style="font-weight:800">❤️ '+G.hearts.n+'</span></div>';h+='<p class="mut">'+esc(subjName(s))+' · '+t('question')+' '+(st.i+1)+' '+t('of')+' '+st.list.length+' · '+t('score')+' '+st.score+'</p>';h+='<div style="font-family:var(--font);font-weight:800;font-size:21px;line-height:1.5;margin-bottom:14px">'+esc(q.q)+'</div><div id="opts">';q.o.forEach(function(o,idx){h+='<button class="opt" data-opt="'+idx+'"><span class="key">'+'ABCD'[idx]+'</span><span>'+esc(o)+'</span></button>';});h+='</div><div id="fb"></div>';box.innerHTML=h;var picked=-1;box.querySelectorAll('[data-opt]').forEach(function(b){b.addEventListener('click',function(){if(picked>=0&&box.dataset.locked)return;picked=+b.getAttribute('data-opt');box.querySelectorAll('.opt').forEach(function(x){x.classList.remove('sel');});b.classList.add('sel');var fb=document.getElementById('fb');if(!fb.querySelector('.btn'))fb.innerHTML='<button class="btn" id="chk">'+t('check')+'</button>';document.getElementById('chk').addEventListener('click',function(){if(picked<0)return;box.dataset.locked='1';var right=picked===q.a;box.querySelectorAll('.opt').forEach(function(x,idx){x.disabled=true;if(idx===q.a)x.classList.add('right');else if(idx===picked)x.classList.add('wrong');});if(right){st.score++;addXP(10);if(st.mode==='mistakes')removeMistake(item.sid,item.idx);}else{G.hearts.n=Math.max(0,G.hearts.n-1);saveG();renderHUD();addMistake(item.sid,item.idx);}document.getElementById('fb').innerHTML='<div class="feedback '+(right?'ok':'no')+'">'+(right?'🎉 '+t('correct'):'💡 '+t('wrong')+' <b>'+'ABCD'[q.a]+'. '+esc(q.o[q.a])+'</b>')+'<br><span style="font-weight:500">'+esc(q.e)+'</span></div><button class="btn '+(right?'':'red')+'" style="margin-top:12px" id="nxt">'+(st.i+1>=st.list.length?t('finish'):t('next'))+'</button>';document.getElementById('nxt').addEventListener('click',function(){delete box.dataset.locked;st.i++;renderQ();});});});});}
function exitQuiz(){quiz=null;document.getElementById('quiz-box').innerHTML='';document.getElementById('quiz-menu').hidden=false;renderAll();}
function finishQuiz(){var st=quiz;var box=document.getElementById('quiz-box');var total=st.list.length;if(st.mode==='subject'){var prev=LS.get('quiz-'+st.id,{best:0});LS.set('quiz-'+st.id,{best:Math.max(prev.best||0,st.score),last:st.score});}if(st.mode==='daily'){G.dailyDone=todayStr;saveG();}var title=st.mode==='daily'?t('dailyDone'):st.mode==='mistakes'?(LANG==='en'?'Mistake review done!':'ทบทวนเสร็จแล้ว!'):(LANG==='en'?'Practice complete!':'ฝึกเสร็จแล้ว!');box.innerHTML='';document.getElementById('quiz-menu').hidden=false;quiz=null;renderAll();celebrate(title,t('score')+': <b>'+st.score+' / '+total+'</b> ('+Math.round(st.score/total*100)+'%) ⭐ XP '+G.xp,t('continue'),null);checkBadges(true);}
/* ===== Extra exercises ===== */
var ex=null;
function startExtra(){if(!heartsGate())return;ex={i:0,score:0,list:EXTRA.slice()};go('quiz');document.getElementById('quiz-menu').hidden=true;renderEx();}
function exHead(){return '<div class="prow"><button class="xbtn" onclick="exitQuiz2()">✕</button><div class="bar blue" style="flex:1"><i style="width:'+Math.round(ex.i/ex.list.length*100)+'%"></i></div><span style="font-weight:800">❤️ '+G.hearts.n+'</span></div>';}
function exitQuiz2(){ex=null;document.getElementById('quiz-box').innerHTML='';document.getElementById('quiz-menu').hidden=false;}
function exFeedback(right,e){if(right){ex.score++;addXP(10);}else{G.hearts.n=Math.max(0,G.hearts.n-1);saveG();renderHUD();}return '<div class="feedback '+(right?'ok':'no')+'">'+(right?'🎉 '+t('correct'):'💡 '+(LANG==='en'?'Not quite':'ยังไม่ถูก'))+'<br><span style="font-weight:500">'+esc(e)+'</span></div><button class="btn" style="margin-top:12px" onclick="nextEx()">'+(ex.i+1>=ex.list.length?t('finish'):t('next'))+'</button>';}
function nextEx(){ex.i++;if(ex.i>=ex.list.length){var sc=ex.score,tt=ex.list.length;exitQuiz2();celebrate(t('extraDone'),t('score')+': <b>'+sc+' / '+tt+'</b>',t('continue'),null);checkBadges(true);return;}renderEx();}
function renderEx(){var box=document.getElementById('quiz-box');var it=ex.list[ex.i];var title=LANG==='en'?it.en:it.th;var h=exHead()+'<div style="font-family:var(--font);font-weight:800;font-size:21px;line-height:1.5;margin-bottom:14px">'+esc(title)+'</div>';
if(it.type==='tf'){h+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><button class="btn" onclick="ansTF(true)">✓ '+t('tfTrue')+'</button><button class="btn red" onclick="ansTF(false)">✕ '+t('tfFalse')+'</button></div><div id="fb"></div>';box.innerHTML=h;return;}
if(it.type==='fill'){h+='<p class="mut">'+t('fillHint')+'</p><input class="blank" id="fill-in" autocomplete="off"><div id="fb" style="margin-top:12px"><button class="btn" onclick="ansFill()">'+t('check')+'</button></div>';box.innerHTML=h;return;}
if(it.type==='match'){ex.selL=-1;ex.doneM={};h+='<p class="mut">'+t('matchHint')+'</p><div class="matchgrid"><div id="mL"></div><div id="mR"></div></div><div id="fb"></div>';box.innerHTML=h;renderMatch();return;}
if(it.type==='order'){ex.picked=[];h+='<p class="mut">'+t('orderHint')+'</p><div class="chiprow" id="ord-pool"></div><div class="card" style="margin-top:14px;min-height:64px"><b>'+(LANG==='en'?'Your order:':'ลำดับของเฟิร์น:')+'</b> <span id="ord-out"></span></div><div id="fb"><button class="btn" onclick="ansOrder()">'+t('check')+'</button></div>';box.innerHTML=h;renderOrderPool();return;}}
function ansTF(v){var it=ex.list[ex.i];document.getElementById('fb').innerHTML=exFeedback(v===it.a,it.e);}
function ansFill(){var it=ex.list[ex.i];var v=(document.getElementById('fill-in').value||'').trim().toLowerCase();var ok=it.ans.some(function(a){return v===String(a).toLowerCase();});document.getElementById('fb').innerHTML=exFeedback(ok,it.e);}
function renderMatch(){var it=ex.list[ex.i];var L=document.getElementById('mL'),R=document.getElementById('mR');var lh='',rh='';it.pairs.forEach(function(p,i){lh+='<button class="matchbtn" style="width:100%;margin-bottom:8px" data-ml="'+i+'">'+esc(p[0])+'</button>';});var order=it.pairs.map(function(_,i){return i;}).sort(function(a,b){return ((a*7+3)%4)-((b*7+3)%4);});order.forEach(function(i){rh+='<button class="matchbtn" style="width:100%;margin-bottom:8px" data-mr="'+i+'">'+esc(it.pairs[i][1])+'</button>';});L.innerHTML=lh;R.innerHTML=rh;L.querySelectorAll('[data-ml]').forEach(function(b){b.addEventListener('click',function(){ex.selL=+b.getAttribute('data-ml');L.querySelectorAll('.matchbtn').forEach(function(x){x.classList.remove('sel');});b.classList.add('sel');});});R.querySelectorAll('[data-mr]').forEach(function(b){b.addEventListener('click',function(){if(ex.selL<0)return;var ri=+b.getAttribute('data-mr');if(ri===ex.selL){ex.doneM[ri]=true;b.classList.add('done');var lb=L.querySelector('[data-ml="'+ri+'"]');if(lb)lb.classList.add('done');ex.selL=-1;L.querySelectorAll('.matchbtn').forEach(function(x){x.classList.remove('sel');});if(Object.keys(ex.doneM).length===it.pairs.length){document.getElementById('fb').innerHTML=exFeedback(true,it.e);}}else{document.getElementById('fb').innerHTML='<div class="feedback no">💡 '+(LANG==='en'?'That pair doesn\u2019t match — try again!':'คู่นี้ยังไม่ตรง — ลองใหม่นะ')+'</div>';}});});}
function renderOrderPool(){var it=ex.list[ex.i];var pool=document.getElementById('ord-pool');var shuffled=it.items.map(function(_,i){return i;}).sort(function(a,b){return ((a*5+1)%3)-((b*5+1)%3);});pool.innerHTML=shuffled.map(function(i){return ex.picked.indexOf(i)>=0?'':'<button class="chip" data-ord="'+i+'">'+esc(it.items[i])+'</button>';}).join('');document.getElementById('ord-out').textContent=ex.picked.map(function(i){return it.items[i];}).join(' → ');pool.querySelectorAll('[data-ord]').forEach(function(b){b.addEventListener('click',function(){ex.picked.push(+b.getAttribute('data-ord'));renderOrderPool();});});}
function ansOrder(){var it=ex.list[ex.i];var ok=ex.picked.length===it.items.length&&ex.picked.every(function(v,i){return v===i;});document.getElementById('fb').innerHTML=exFeedback(ok,it.e);}
/* ===== Flashcards ===== */
var fcIdx=0,fcFlip=false;
function renderFC(){var box=document.getElementById('fc-box');if(!box)return;var known=LS.get('fc-known',[]);var total=FLASH.length;if(fcIdx>=total)fcIdx=0;var c=LANG==='en'?FLASH_EN[fcIdx]:FLASH[fcIdx];var isK=known.indexOf(fcIdx)>=0;box.innerHTML='<div class="fc'+(fcFlip?' flip':'')+'" id="fc-card"><div class="fc-in"><div class="fc-face"><p class="mut">'+t('card')+' '+(fcIdx+1)+'/'+total+' · ✓ '+known.length+(isK?' · ✓':'')+'</p><div class="q">'+esc(c[0])+'</div><p class="mut">'+t('tapFlip')+'</p></div><div class="fc-face fc-back"><div class="a">'+esc(c[1])+'</div><p class="mut">'+(LANG==='en'?'Thai term stays on the exam — learn both!':'แตะการ์ดเพื่อกลับด้าน')+'</p></div></div></div><div class="chiprow" style="justify-content:center"><button class="chip" id="fc-prev">'+t('prev')+'</button><button class="chip" id="fc-again">'+t('notYet')+'</button><button class="chip" id="fc-know">'+t('known')+'</button><button class="chip" id="fc-next">'+t('nextC')+'</button></div>';
document.getElementById('fc-card').addEventListener('click',function(){fcFlip=!fcFlip;renderFC();});
document.getElementById('fc-prev').addEventListener('click',function(){fcIdx=(fcIdx+total-1)%total;fcFlip=false;renderFC();});
document.getElementById('fc-next').addEventListener('click',function(){fcIdx=(fcIdx+1)%total;fcFlip=false;renderFC();});
document.getElementById('fc-know').addEventListener('click',function(){var k=LS.get('fc-known',[]);if(k.indexOf(fcIdx)<0){k.push(fcIdx);LS.set('fc-known',k);addXP(5);}fcIdx=(fcIdx+1)%total;fcFlip=false;renderFC();renderBadges();});
document.getElementById('fc-again').addEventListener('click',function(){var k=LS.get('fc-known',[]);var p=k.indexOf(fcIdx);if(p>=0){k.splice(p,1);LS.set('fc-known',k);}fcIdx=(fcIdx+1)%total;fcFlip=false;renderFC();});}
/* ===== Mock exam (kept full: 150 Q, 3h, per-part rule) ===== */
var mock=null,mockTimer=null;
function buildMockSet(){var set=[];SUBJECTS.forEach(function(s){QUESTIONS[s.id].forEach(function(q,i){set.push({sid:s.id,idx:i,q:q});});});return set;}
function startMock(){mock={set:buildMockSet(),ans:{},left:180*60};document.getElementById('mock-intro').hidden=true;go('mock');renderMock();clearInterval(mockTimer);mockTimer=setInterval(function(){mock.left--;var tb=document.getElementById('mock-time');if(tb)tb.textContent=fmtTime(mock.left);if(mock.left<=0)finishMock(true);},1000);}
function fmtTime(s){if(s<0)s=0;var h=Math.floor(s/3600),m=Math.floor(s%3600/60),ss=s%60;return (h>0?h+':':'')+('0'+m).slice(-2)+':'+('0'+ss).slice(-2);}
function renderMock(){var box=document.getElementById('mock-box');var done=Object.keys(mock.ans).length;var h='<div class="timerbar">⏱ '+t('timeLeft')+' <span id="mock-time">'+fmtTime(mock.left)+'</span> · '+t('answered')+' '+done+'/150</div>';var cur='';mock.set.forEach(function(item,idx){if(item.sid!==cur){cur=item.sid;var s=subjById(cur);h+='<div class="unit-banner" style="background:'+SUBJ_COLOR[cur][0]+'"><span>'+s.icon+' '+esc(subjName(s))+'</span><span>'+QUESTIONS[cur].length+' '+t('qs')+'</span></div>';}var q=item.q;h+='<div class="card"><p class="mut">'+t('question')+' '+(idx+1)+'</p><p style="font-weight:700;font-size:17.5px;line-height:1.55">'+esc(q.q)+'</p>';q.o.forEach(function(o,oi){var sel=mock.ans[idx]===oi;h+='<button class="opt'+(sel?' sel':'')+'" data-m="'+idx+'" data-o="'+oi+'"><span class="key">'+'ABCD'[oi]+'</span><span>'+esc(o)+'</span></button>';});h+='</div>';});h+='<button class="btn red" onclick="finishMock(false)">'+t('submitMock')+'</button>';box.innerHTML=h;box.querySelectorAll('[data-m]').forEach(function(b){b.addEventListener('click',function(){var y=window.scrollY;mock.ans[+b.getAttribute('data-m')]=+b.getAttribute('data-o');renderMock();window.scrollTo(0,y);});});}
function finishMock(auto){if(!mock)return;clearInterval(mockTimer);var p1=0,p2=0,per={};SUBJECTS.forEach(function(s){per[s.id]=0;});var wrong=[];mock.set.forEach(function(item,idx){var s=subjById(item.sid);if(mock.ans[idx]===item.q.a){per[item.sid]++;if(s.part===1)p1++;else p2++;}else{wrong.push({idx:idx,item:item,pick:mock.ans[idx]});addMistake(item.sid,item.idx);}});var total=p1+p2,pass1=p1>=24,pass2=p2>=66,pass=pass1&&pass2;var hist=LS.get('mock-history',[]);hist.push({t:Date.now(),total:total,p1:p1,p2:p2,pass:pass});LS.set('mock-history',hist);addXP(pass?50:25);var h='<div class="card"><div style="text-align:center">'+mascotSVG(90,pass?'cheer':'sad')+'</div><div class="big" style="text-align:center">'+(auto?t('timeUp'):'')+t('mockResult')+'</div><p style="font-size:34px;text-align:center;font-family:var(--font);font-weight:800;margin:4px 0">'+total+' / 150</p><div class="feedback '+(pass?'ok':'no')+'" style="text-align:center"><b>'+(pass?t('pass'):t('fail'))+'</b><br>'+t('part1')+': '+p1+'/40 '+(pass1?'✓':'✗ (≥24)')+' · '+t('part2')+': '+p2+'/110 '+(pass2?'✓':'✗ (≥66)')+'</div><table>';SUBJECTS.forEach(function(s){h+='<tr><td>'+s.icon+' '+esc(subjName(s))+'</td><td><b>'+per[s.id]+'/'+QUESTIONS[s.id].length+'</b></td></tr>';});h+='</table><div class="chiprow" style="margin-top:12px"><button class="chip" onclick="restartMock()">'+t('again')+'</button><button class="chip" onclick="go(\'home\')">'+t('backHome')+'</button></div></div>';if(wrong.length){h+='<div class="big" style="font-size:21px">'+t('reviewWrong')+' ('+wrong.length+')</div>';wrong.forEach(function(w){var q=w.item.q;h+='<div class="card"><p class="mut">'+t('question')+' '+(w.idx+1)+' · '+esc(subjName(subjById(w.item.sid)))+'</p><p style="font-weight:700">'+esc(q.q)+'</p><p>'+t('yourAns')+': <b style="color:var(--red)">'+(w.pick===undefined?t('notAnswered'):'ABCD'[w.pick]+'. '+esc(q.o[w.pick]))+'</b></p><p>'+t('rightAns')+': <b style="color:var(--green-d)">'+'ABCD'[q.a]+'. '+esc(q.o[q.a])+'</b></p><div class="hl" style="margin-bottom:0">'+esc(q.e)+'</div></div>';});}else h+='<div class="card" style="background:var(--green-soft)"><b>'+t('perfect')+'</b></div>';document.getElementById('mock-box').innerHTML=h;document.getElementById('mock-intro').hidden=false;renderMockHistory();window.scrollTo(0,0);mock=null;if(pass)confetti();checkBadges(true);}
function restartMock(){document.getElementById('mock-box').innerHTML='';startMock();}
function renderMockHistory(){var el=document.getElementById('mock-history');if(!el)return;var hist=LS.get('mock-history',[]);if(!hist.length){el.innerHTML='<p class="mut">'+(LANG==='en'?'No mock yet — your first one matters most. Go for it!':'ยังไม่เคยทำสอบจำลอง — ครั้งแรกสำคัญที่สุด ลองเลย')+'</p>';return;}var last=hist[hist.length-1];el.innerHTML='<p class="mut">'+hist.length+' '+(LANG==='en'?'attempts · Latest':'ครั้ง · ล่าสุด')+': <b>'+last.total+'/150</b> ('+last.p1+'/40 · '+last.p2+'/110) — '+(last.pass?'<b style="color:var(--green-d)">'+t('pass')+'</b>':'<b style="color:var(--red)">'+t('fail')+'</b>')+'</p>';}
